/****************************************************************************
 * arch/arm/src/armv7-m/vg_diag.h
 *
 * Temporary QA-04 diagnostic counters.  This header is not part of the
 * product; it exists to answer one question on the board: when the system
 * freezes (g_system_ticks stops while SYST_CVR keeps running), which
 * interrupt paths are still being entered and left, and does a normal
 * thread still make progress?
 *
 * Rules for everything in here:
 *   - interrupt context only does a 32-bit increment and, where noted, a
 *     register read; no printing, no waiting, no allocation, no locks;
 *   - every field is plain RAM (BSS), read later with a debugger;
 *   - the counters are free-running and never cleared, so a freeze can be
 *     compared with a snapshot taken earlier in the same boot.
 *
 * Every site is guarded by CONFIG_ARCH_VG_DIAG so the header can stay in the
 * tree while the option is off.
 ****************************************************************************/

#ifndef __ARCH_ARM_SRC_ARMV7_M_VG_DIAG_H
#define __ARCH_ARM_SRC_ARMV7_M_VG_DIAG_H

/****************************************************************************
 * Included Files
 ****************************************************************************/

#include <nuttx/config.h>

#include <stdint.h>

#ifdef CONFIG_ARCH_VG_DIAG

/****************************************************************************
 * Public Types
 ****************************************************************************/

struct vg_diag_s
{
  /* USART2 interrupt path (the ESP8266 link; IRQ 54 on this part).
   *
   * Entry and exit are counted at up_interrupt()'s first and last
   * statement.  A difference only means a call was still in progress at the
   * moment of the snapshot; it is not by itself evidence of a stuck
   * handler.  The recv counters split the receive work from the rest so a
   * handler that keeps looping inside uart_recvchars() can be told apart
   * from one that returns normally each time.
   */

  volatile uint32_t u2_entry;      /* up_interrupt() entered */
  volatile uint32_t u2_exit;       /* up_interrupt() about to return */
  volatile uint32_t u2_rxne;       /* RXNE branch taken */
  volatile uint32_t u2_rx_before;  /* just before uart_recvchars() */
  volatile uint32_t u2_rx_after;   /* just after uart_recvchars() */
  volatile uint32_t u2_tc;         /* RS-485 TC branch taken */
  volatile uint32_t u2_txe;        /* TXE branch taken */
  volatile uint32_t u2_idle;       /* IDLE flag seen in ISR */
  volatile uint32_t u2_last_isr;   /* last raw ISR value */
  volatile uint32_t u2_last_ie;    /* last priv->ie value */
  volatile uint32_t u2_last_pc;    /* LR inside the last entry */
  volatile uint32_t u2_last_xpsr;  /* xPSR inside the last entry */

  /* SysTick (IRQ 15).  Entry is the first statement of stm32_timerisr(),
   * exit the last one after nxsched_process_timer() returned.  A frozen
   * tick with both counters still moving means the ISR runs but the tick
   * does not advance; both stopped means the vector is never entered.
   */

  volatile uint32_t systick_entry;
  volatile uint32_t systick_exit;
  volatile uint32_t systick_last_pc;
  volatile uint32_t systick_last_xpsr;

  /* PendSV (IRQ 14), counted in arm_doirq().  The saved state is from the
   * most recent entry, so a frozen system shows what the CPU was doing when
   * it last switched.
   */

  volatile uint32_t pendsv_entry;
  volatile uint32_t pendsv_exit;
  volatile uint32_t pendsv_basepri;
  volatile uint32_t pendsv_primask;
  volatile uint32_t pendsv_ipsr;
  volatile uint32_t pendsv_pc;      /* interrupted PC from the stack frame */
  volatile uint32_t pendsv_xpsr;

  /* Every exception entry through arm_doirq(), by IRQ number.  The first 16
   * slots are the system vectors; the rest cover the peripheral IRQs that
   * matter here (USART2 54, USART3 55, UART7 82 on this part).
   */

  volatile uint32_t irq_entry[96];
  volatile uint32_t irq_last_irq;

  /* Plain thread progress.  This is the HMI acquisition loop, a normal
   * pthread that polls the bus and sleeps 200 ms per cycle.  It is written
   * from thread mode, not from an interrupt.
   */

  volatile uint32_t thread_loops;
  volatile uint32_t thread_ticks;   /* clock_gettime(CLOCK_MONOTONIC) ms */
};

/****************************************************************************
 * Public Data
 ****************************************************************************/

extern struct vg_diag_s g_vg_diag;

/****************************************************************************
 * Public Function Prototypes
 ****************************************************************************/

/* Snapshot helpers callable from thread context only (the NSH console).
 * They are read-only and return values the shell can print.
 */

uint32_t vg_diag_thread_loops(void);
uint32_t vg_diag_thread_ticks(void);
void     vg_diag_thread_loop(void);

#endif /* CONFIG_ARCH_VG_DIAG */
#endif /* __ARCH_ARM_SRC_ARMV7_M_VG_DIAG_H */

/****************************************************************************
 * arch/arm/src/armv7-m/vg_diag.h
 *
 * Temporary QA-04 diagnostic counters (VelaGuard maintenance branch).
 *
 * Purpose: when the system freezes (g_system_ticks stops while SYST_CVR
 * keeps running), decide from one read-only snapshot which interrupt paths
 * are still being entered and left, whether SysTick is entered at all, and
 * whether a normal thread still makes progress.
 *
 * Rules for every site in here:
 *   - interrupt context only does a 32-bit increment and, at some entry
 *     points, a register read; no printing, no waiting, no allocation and
 *     no locks;
 *   - all state is plain RAM, meant to be read later with a debugger;
 *   - counters are free-running and never cleared, so a snapshot taken
 *     before the run can be subtracted from the snapshot taken at the
 *     freeze.
 *
 * Every counter is a separate global symbol on purpose: the release build
 * carries no DWARF for kernel objects, and a debugger can still read a
 * symbol by name.
 *
 * Entry and exit counters are independent.  A difference between them only
 * means a call was still in progress at the instant of the snapshot; it is
 * not by itself evidence of a stuck handler.  Judge that together with the
 * halted PC, the interrupted PC recorded at the last PendSV, and the other
 * counters.
 ****************************************************************************/

#ifndef __ARCH_ARM_SRC_ARMV7_M_VG_DIAG_H
#define __ARCH_ARM_SRC_ARMV7_M_VG_DIAG_H

/****************************************************************************
 * Included Files
 ****************************************************************************/

#include <nuttx/config.h>

#include <stdint.h>

#ifdef CONFIG_ARCH_VG_DIAG

/****************************************************************************
 * Public Data
 ****************************************************************************/

/* USART2 (the ESP8266 link, NuttX IRQ 54 / vector 54).  up_interrupt() is
 * the driver-level handler, so these count handler entries regardless of
 * which vector path delivered them.
 */

extern volatile uint32_t g_vgdiag_u2_entry;
extern volatile uint32_t g_vgdiag_u2_exit;
extern volatile uint32_t g_vgdiag_u2_rxne;
extern volatile uint32_t g_vgdiag_u2_rx_before;
extern volatile uint32_t g_vgdiag_u2_rx_after;
extern volatile uint32_t g_vgdiag_u2_tc;
extern volatile uint32_t g_vgdiag_u2_txe;
extern volatile uint32_t g_vgdiag_u2_idle;
extern volatile uint32_t g_vgdiag_u2_last_isr;
extern volatile uint32_t g_vgdiag_u2_last_ie;
extern volatile uint32_t g_vgdiag_u2_last_lr;
extern volatile uint32_t g_vgdiag_u2_last_xpsr;

/* SysTick (vector 15).  Entry is the first statement of stm32_timerisr(),
 * exit the last statement after nxsched_process_timer() returned.  If entry
 * and exit both advance while g_system_ticks does not, the ISR runs but the
 * tick does not advance; if both stop, the vector is never entered.
 */

extern volatile uint32_t g_vgdiag_systick_entry;
extern volatile uint32_t g_vgdiag_systick_exit;
extern volatile uint32_t g_vgdiag_systick_last_lr;
extern volatile uint32_t g_vgdiag_systick_last_xpsr;
extern volatile uint32_t g_vgdiag_systick_basepri;
extern volatile uint32_t g_vgdiag_systick_primask;

/* PendSV (vector 14), counted in arm_doirq().  The saved values are from the
 * most recent entry, so a frozen system shows what the CPU was doing when it
 * last switched.
 */

extern volatile uint32_t g_vgdiag_pendsv_entry;
extern volatile uint32_t g_vgdiag_pendsv_exit;
extern volatile uint32_t g_vgdiag_pendsv_basepri;
extern volatile uint32_t g_vgdiag_pendsv_primask;
extern volatile uint32_t g_vgdiag_pendsv_ipsr;
extern volatile uint32_t g_vgdiag_pendsv_pc;
extern volatile uint32_t g_vgdiag_pendsv_xpsr;

/****************************************************************************
 * Inline Helpers
 ****************************************************************************/

static inline uint32_t vg_diag_xpsr(void)
{
  uint32_t xpsr;

  __asm__ __volatile__ ("\tmrs %0, xpsr\n" : "=r" (xpsr) : : "memory");
  return xpsr;
}

#endif /* CONFIG_ARCH_VG_DIAG */
#endif /* __ARCH_ARM_SRC_ARMV7_M_VG_DIAG_H */

